cfg = dict(defaults)
for name, value in env.items():
    if not name.startswith("APP_"):
        continue
    key = name[4:].lower()
    if key not in defaults:
        continue

    default = defaults[key]
    if isinstance(default, bool):
        value = value.lower() in {"1", "true", "yes", "on"}
    else:
        value = type(default)(value)
    cfg[key] = value
return cfg
